statement:
Split the integer array `nums` into rows of a 2D array so that:

- every element of `nums` ends up in exactly one row, and the rows hold nothing else (each value appears in total as many times as in `nums`);
- no row contains the same integer more than once;
- there are as few rows as possible.

Rows may have different lengths. Several arrangements can be valid; return any one of them (the order of the rows and of the values inside a row is free).

checker:
function check([nums], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== expected.length) return false;
  const left = new Map();
  for (const v of nums) left.set(v, (left.get(v) || 0) + 1);
  for (const row of actual) {
    if (!Array.isArray(row) || row.length === 0) return false;
    const seen = new Set();
    for (const v of row) {
      if (seen.has(v)) return false;
      seen.add(v);
      const c = left.get(v);
      if (!c) return false;
      left.set(v, c - 1);
    }
  }
  for (const c of left.values()) if (c !== 0) return false;
  return true;
}

validator:
function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 200) return 'nums needs 1 to 200 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > nums.length)) return 'Each value is between 1 and nums.length.';
  return null;
}

