function findMatrix(nums) {
  const count = new Array(nums.length + 1).fill(0);
  const rows = [];
  for (const num of nums) {
    if (count[num] === rows.length) {
      rows.push([]);
    }
    rows[count[num]].push(num);
    count[num]++;
  }
  return rows;
}

