function findMatrix(nums) {
  // Peel off one copy of every remaining distinct value per row until nothing is left.
  let remaining = nums.slice();
  const result = [];
  while (remaining.length > 0) {
    const row = [];
    const rest = [];
    for (const v of remaining) {
      if (row.includes(v)) rest.push(v);
      else row.push(v);
    }
    result.push(row);
    remaining = rest;
  }
  return result;
}

