function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(150, 200) : pick(1, 10);
  const mode = rand();
  const distinct = mode < 0.3 ? n : mode < 0.6 ? pick(1, Math.min(n, 4)) : pick(1, n);
  const values = Array.from({ length: distinct }, () => pick(1, n));
  return [Array.from({ length: n }, () => values[Math.floor(rand() * values.length)])];
}
